import boto3
import json
from io import BytesIO

def extract_expense_fields(document_bytes: bytes) -> dict:
    """
    Extracts expense fields from a document using Amazon Textract AnalyzeExpense
    and normalizes them into a standard JSON schema.

    Args:
        document_bytes: The byte content of the document (e.g., PDF, JPEG, PNG).

    Returns:
        A dictionary containing the normalized expense fields.
        Example:
        {
            "total_amount": 123.45,
            "date": "2023-10-27",
            "vendor_name": "Example Store Inc.",
            "currency": "USD"
        }
    """

    # Initialize the Amazon Textract client
    # AWS credentials should be configured in environment variables (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY)
    # or via other boto3 configuration methods.
    textract_client = boto3.client('textract', region_name='us-east-1') # Specify a region

    response = textract_client.analyze_expense(
        Document={'Bytes': document_bytes}
    )

    normalized_expense = {
        "total_amount": None,
        "date": None,
        "vendor_name": None,
        "currency": None,
        "line_items": []
    }

    if response.get('ExpenseDocuments'):
        # Assuming we process the first expense document found
        expense_doc = response['ExpenseDocuments'][0]

        # Extract Summary Fields
        for field in expense_doc.get('SummaryFields', []):
            field_type = field.get('Type', {}).get('Text')
            field_value = field.get('ValueDetection', {}).get('Text')
            currency_symbol = field.get('Currency', {}).get('Symbol')

            if field_type == 'TOTAL':
                if field_value:
                    try:
                        normalized_expense['total_amount'] = float(field_value.replace('$', '').replace(',', ''))
                    except ValueError:
                        pass # Handle cases where conversion fails
                if currency_symbol:
                    normalized_expense['currency'] = currency_symbol
            elif field_type == 'EXPENSE_DATE':
                normalized_expense['date'] = field_value
            elif field_type == 'VENDOR_NAME':
                normalized_expense['vendor_name'] = field_value
            elif field_type == 'CURRENCY' and not normalized_expense['currency']:
                 # If currency wasn't derived from TOTAL field, try this
                 normalized_expense['currency'] = field_value


        # Extract Line Items (simplified)
        for group in expense_doc.get('LineItemGroups', []):
            for item in group.get('LineItems', []):
                line_item_data = {}
                for field in item.get('LineItemFields', []):
                    field_type = field.get('Type', {}).get('Text')
                    field_value = field.get('ValueDetection', {}).get('Text')
                    if field_type == 'ITEM':
                        line_item_data['description'] = field_value
                    elif field_type == 'PRICE':
                        try:
                            line_item_data['price'] = float(field_value)
                        except (ValueError, TypeError):
                            pass
                    elif field_type == 'QUANTITY':
                        try:
                            line_item_data['quantity'] = float(field_value)
                        except (ValueError, TypeError):
                            pass
                if line_item_data:
                    normalized_expense['line_items'].append(line_item_data)

    return normalized_expense
